import React, { useEffect, useState, useMemo, useRef } from 'react';
import { MapContainer, TileLayer, useMap, ScaleControl } from 'react-leaflet';
import L from 'leaflet';
import { Home, Info } from 'lucide-react';
import 'leaflet/dist/leaflet.css';
import { Container } from "react-bootstrap";
import './WhereFrom.css';

delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',
  iconUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',
  shadowUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',
});

// Component that manages static layers once
function StaticLayers({ locations, averageLocation, avgDistance }) {
  const map = useMap();

  useEffect(() => {
    if (!map) return;

    // Clear existing layers first (but preserve tile layers and average marker)
    map.eachLayer((layer) => {
      if ((layer instanceof L.Marker && !layer.options.isAverageMarker) || layer instanceof L.Polyline) {
        map.removeLayer(layer);
      }
    });

    // Add red markers
    locations.forEach((loc) => {
      const size = Math.max(25, Math.min(45, 20 + loc.weight * 3));
      const yearsDisplay = Math.round(loc.years * 10) / 10; // Show one decimal place
      const icon = L.divIcon({
        className: 'custom-location-marker',
        html: `<div style="
          width:${size}px;height:${size}px;background:#dc2626;border:3px solid white;
          border-radius:50%;display:flex;align-items:center;justify-content:center;
          color:white;font-weight:bold;font-size:${Math.max(10,size/4)}px;
        ">${yearsDisplay}</div>`,
        iconSize: [size, size],
        iconAnchor: [size/2, size/2],
      });
      const marker = L.marker([loc.lat, loc.lng], { icon }).addTo(map);
      marker.bindPopup(`<div style="text-align:center;min-width:150px;"><strong>${loc.name}</strong><br/><small>${yearsDisplay} years</small></div>`);
    });

    // Draw chronological path connecting locations in order
    for (let i = 0; i < locations.length - 1; i++) {
      const currentLoc = locations[i];
      const nextLoc = locations[i + 1];
      
      L.polyline(
        [[currentLoc.lat, currentLoc.lng], [nextLoc.lat, nextLoc.lng]], 
        {
          color: '#2564eb4f', // Blue color for the path
          weight: 3,
          opacity: 0.7,
          dashArray: '10,5' // Dashed line pattern
        }
      ).addTo(map);
    }

  }, [map, locations, averageLocation, avgDistance]);

  return null;
}

// Component to manage moving green marker
function AverageMarker({ position }) {
  const map = useMap();
  const markerRef = useRef(null);

  useEffect(() => {
    if (!map) return;

    // create marker once
    const avgIcon = L.divIcon({
      className: 'custom-average-marker',
      html: `<div style="
        width:30px;height:30px;background:#059669;border:3px solid white;
        clip-path: polygon(50% 0%,61% 35%,98% 35%,68% 57%,79% 91%,50% 70%,21% 91%,32% 57%,2% 35%,39% 35%);
        box-shadow:0 2px 8px rgba(0,0,0,0.3);
      "></div>`,
      iconSize: [30, 30],
      iconAnchor: [15, 15],
    });

    markerRef.current = L.marker([position.lat, position.lng], { 
      icon: avgIcon, 
      isAverageMarker: true 
    }).addTo(map);
    markerRef.current.bindPopup(`<div style="text-align:center;min-width:180px;">
      <strong>🏠 Your Average Location</strong><br/>
      <span style="color:#059669;font-weight:bold;">Where you're "from"</span><br/>
      <small>${position.lat.toFixed(4)}, ${position.lng.toFixed(4)}</small>
    </div>`);

    return () => {
      if (markerRef.current) {
        map.removeLayer(markerRef.current);
      }
    };
  }, [map]);

  // update marker position when `position` changes
  useEffect(() => {
    if (markerRef.current) {
      markerRef.current.setLatLng([position.lat, position.lng]);
      markerRef.current.getPopup().setContent(`<div style="text-align:center;min-width:180px;">
        <strong>🏠 Your Average Location</strong><br/>
        <span style="color:#059669;font-weight:bold;">Where you're "from"</span><br/>
        <small>${position.lat.toFixed(4)}, ${position.lng.toFixed(4)}</small>
      </div>`);
    }
  }, [position]);

  return null;
}


function WhereFrom() {
  
    const birthday = new Date('1993-09-24');
    const movedToSDDate = new Date('2024-03-01');
    const [prevAvgLocation, setPrevAvgLocation] = useState({ lat: 0, lng: 0 });

    const baseLocations = [
        { name: 'Muscatine, IA', lat: 41.4402, lng: -91.0022, years: 18 },
        { name: 'Grinnell, IA', lat: 41.7407, lng: -92.7265, years: 4 },
        { name: 'Springfield, MO', lat: 37.2089, lng: -93.2923, years: 1 },
        { name: 'Fairfax, VA', lat: 38.8411, lng: -77.3064, years: 4 },
        { name: 'Pasadena, CA', lat: 34.1478, lng: -118.1445, years: 2.5 },
    ];

    const getAge = () => (Date.now() - birthday.getTime()) / (365.25 * 24 * 3600 * 1000);
    //const getSDYears = () => (Date.now() - movedToSDDate.getTime()) / (365.25 * 24 * 3600 * 1000);
    const getSDYears = () => {
        const actualYears = (Date.now() - movedToSDDate.getTime()) / (365.25 * 24 * 3600 * 1000);
        //const extraSimulatedDays = (Date.now() % 100000) / 1000; // resets every 100 seconds to avoid overflow
        return actualYears; // + (extraSimulatedDays / 365.25);
    };
    
    const [age, setAge] = useState(getAge());
    const [sdYears, setSDYears] = useState(getSDYears());

    useEffect(() => {
    const id = setInterval(() => {
      setAge(getAge());
      setSDYears(getSDYears());
    }, 1000); // every 5s
    return () => clearInterval(id);
  }, [birthday, movedToSDDate]);

  const locations = useMemo(() => {
    const allLocations = [
      ...baseLocations,
      { name: 'San Diego, CA', lat: 32.7157, lng: -117.1611, years: Math.max(0, sdYears) }
    ];
    
    return allLocations.map((loc) => ({
      ...loc,
      weight: age > 0 ? loc.years / age : 0,
    }));
  }, [age, sdYears]);

  const averageLocation = useMemo(() => {
    const totalWeight = locations.reduce((s, l) => s + l.weight, 0);
    if (totalWeight === 0) return { lat: 39.8283, lng: -98.5795 };
    const lat =
      locations.reduce((s, l) => s + l.lat * l.weight, 0) / totalWeight;
    const lng =
      locations.reduce((s, l) => s + l.lng * l.weight, 0) / totalWeight;
    return { lat, lng };
  }, [locations]);

  const avgDistance = useMemo(() => {
    const distances = locations.map((loc) => {
      const lat1 = (loc.lat * Math.PI) / 180;
      const lat2 = (averageLocation.lat * Math.PI) / 180;
      const dLat = ((averageLocation.lat - loc.lat) * Math.PI) / 180;
      const dLng = ((averageLocation.lng - loc.lng) * Math.PI) / 180;
      const a =
        Math.sin(dLat / 2) ** 2 +
        Math.cos(lat1) *
          Math.cos(lat2) *
          Math.sin(dLng / 2) ** 2;
      return 6371000 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    });
    return distances.reduce((s, d) => s + d, 0) / distances.length || 0;
  }, [locations, averageLocation]);

  const [showInfo, setShowInfo] = useState(false);

  return (
    <Container fluid className="wherefrom-section" id="wherefrom" style={{ paddingTop: "80px" }}>
      <Container className="wherefrom-content">
        <button
          onClick={() => setShowInfo(!showInfo)}
          className="p-2 rounded-full bg-blue-100 hover:bg-blue-200 transition-colors"
        >
          <Info className="w-5 h-5 text-blue-600" />
        </button>

      <MapContainer
        center={[39.8283, -98.5795]}
        zoom={4}
        scrollWheelZoom
        className="w-full h-96 border border-gray-300 rounded-lg"
      >
        <TileLayer
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          attribution="© OpenStreetMap contributors"
        />
        <ScaleControl 
            position="bottomleft" 
            metric={true} 
            imperial={false}
        />
        <StaticLayers
          locations={locations}
          averageLocation={averageLocation}
          avgDistance={avgDistance}
        />
        <AverageMarker position={averageLocation} />
      </MapContainer>
      <h6 style={{ 
          fontFamily: "Inter, sans-serif", 
          textAlign: "center",
          fontWeight: 100,
          fontSize: '1.5em',
          color: '#f3f3fa',
          marginTop: '4rem',
          marginBottom: '2rem',
        }}>
          I was born in Muscatine, Iowa, but I've been fortunate enough to live in many different places! I now live in San Diego. My (weighted) average location is {averageLocation.lat.toFixed(8)}, {averageLocation.lng.toFixed(8)}, and I'm moving a few meters towards San Diego every day!
        </h6>
    </Container>
    </Container>
  );
}

export default WhereFrom;