import React, { useState, useEffect } from 'react';

function PenguinSayBubble({ message }) {
  const [displayed, setDisplayed] = useState('\u00A0');
  const [mouthOpen, setMouthOpen] = useState(false);

  useEffect(() => {
    let i = 0;
    let phase = 'typing';
    const interval = setInterval(() => {
      if (phase === 'typing') {
        setDisplayed(message.slice(0, i + 1));
        setMouthOpen(i % 2 === 0); // animate beak open/close
        i++;
        if (i > message.length) phase = 'erase';
      } else if (phase === 'erase') {
        setDisplayed('\u00A0');
        setMouthOpen(false);
        i = 0;
        phase = 'typing';
      }
    }, 350);
    return () => clearInterval(interval);
  }, [message]);

  // Simple penguin with a speech bubble
  function buildSpeechBubble(text) {
    const lines = text.split('\n');
    const maxLen = Math.max(...lines.map(l => l.length), 1);
    const top = ' ' + '_'.repeat(maxLen + 2);
    const bottom = ' ' + '-'.repeat(maxLen + 2);
    const bubble = [
      top,
      ...lines.map(line => `< ${line.padEnd(maxLen, ' ')} >`),
      bottom,
    ];
    return bubble.join('\n');
  }

  // Cute static penguin inspired by Super Mario 64 (rounded, simple, not tiger-like)
  const penguin = [
    "  \\",
    "    \\",
    "    _~_",
    "    (o o)",
    "    /  V  \\",
    "    /(  _  )\\",
    "    ^^ ^^"
  ].join('\n');

  return (
    <pre
      style={{
        backgroundColor: 'transparent',
        padding: '1rem',
        borderRadius: '8px',
        fontFamily: 'monospace',
        whiteSpace: 'pre',
        fontSize: '0.9em',
        marginRight: '-3.8rem',
        zIndex: 2,
        position: 'relative',
      }}
    >
      {buildSpeechBubble(displayed) + '\n' + penguin}
    </pre>
  );
}

export default PenguinSayBubble;